            // Mark as invalid
            radioInputs.forEach(input => input.setAttribute('aria-invalid', 'true'));
            errorMsg.textContent = 'Error: Please select a notification preference.';
            errorMsg.classList.remove('sr-only');

            // Focus first invalid control
            radioInputs[0].focus();
